# _common.R: shared setup for every page. Pages read ONLY the small committed
# tables in data/final/ (regenerated by targets::tar_make()), so the site can be
# rendered from a fresh clone without the raw data.
suppressPackageStartupMessages({
  library(dplyr); library(tidyr); library(ggplot2); library(readr); library(stringr); library(purrr)
  library(gt); library(reactable); library(htmltools)
})
source("../R/utils.R")
source("../R/11_site_plots.R")
knitr::opts_chunk$set(fig.align = "center", out.width = "100%")

rd <- function(name) read_csv(file.path("../data/final", paste0(name, ".csv")), show_col_types = FALSE)
facts <- rd("facts")
fx <- function(key) { v <- facts$value[facts$key == key]; if (!length(v)) stop("missing fact: ", key); v }
fx_date <- function(key) as.Date(fx(key), origin = "1970-01-01")
pct <- function(x, acc = 1) scales::percent(x, accuracy = acc)
num <- function(x, d = 1) formatC(x, format = "f", digits = d, big.mark = ",")
cm <- function(x) scales::comma(x)
pts <- function(x, d = 1) paste0(if (x >= 0) "+" else "", formatC(x, format = "f", digits = d))
ri <- rd("robbery_index") |> mutate(tier = factor(tier, names(tier_cols)))
ri_nd <- ri |> filter(winner != "draw")
fight_label <- function(w, l) paste0(w, " def. ", l)
